fn binary_search_recursive(v: &[i32], elem: i32, c: isize, f: isize) -> isize {
    // If the search interval is empty, the last index ≤ target is f (which may be -1).
    if c > f {
        return f;
    }

    // Compute midpoint
    let mid = c + (f - c) / 2;
    let mid_usize = mid as usize;

    if v[mid_usize] <= elem {
        // v[mid] is ≤ target, so the boundary must be at mid or to its right
        binary_search_recursive(v, elem, mid + 1, f)
    } else {
        // v[mid] is > target, so the boundary is to the left of mid
        binary_search_recursive(v, elem, c, mid - 1)
    }
}

